/**
 * Connector Contracts — Core Abstractions for the Integration Fabric
 *
 * This module defines the foundational types and base classes for the connector
 * system. Everything the fabric produces, consumes, or manages is defined here.
 *
 * All types use JSDoc for documentation. No TypeScript — stays consistent with
 * the rest of the monorepo.
 *
 * @module connectors/contracts
 */
import { randomUUID } from "crypto";

// ─── ConnectorMode Enum ─────────────────────────────────────────────────────

/**
 * Interaction modes a connector can support.
 * Each connector declares which modes it implements via its manifest.
 * The fabric routes requests through the appropriate transport based on mode.
 *
 * @readonly
 * @enum {string}
 */
export const ConnectorMode = Object.freeze({
  /** On-demand fetch (query, REST GET). Replaces DataSource.execute() */
  PULL: "PULL",

  /** Write / trigger action (REST POST, DB insert, send message) */
  PUSH: "PUSH",

  /** Continuous real-time feed (SSE, WebSocket, MQTT). Returns async iterator */
  STREAM: "STREAM",

  /** Durable event subscription (Kafka consumer, CDC, webhooks) */
  SUBSCRIBE: "SUBSCRIBE",

  /** Large dataset processing (S3 files, CSV import). Chunked with progress */
  BATCH: "BATCH",

  /** Inbound push from third-party — receive only (Stripe, GitHub webhooks) */
  WEBHOOK: "WEBHOOK",
});

// ─── ConnectorEvent ─────────────────────────────────────────────────────────

/**
 * Universal output unit. Everything the fabric produces is a ConnectorEvent.
 * Workflow engine, widget engine, dashboards all consume this shape.
 * No consumer needs to know whether data came from a DB pull, Kafka message,
 * webhook POST, or IoT reading.
 *
 * @typedef {Object} ConnectorEvent
 * @property {string} eventId              - Unique event ID (UUIDv4)
 * @property {string} connectorType        - e.g. 'postgresql', 'mqtt', 'stripe-webhook'
 * @property {string} connectorInstanceId  - tenant-scoped datasource ID
 * @property {string} tenantId             - tenant that owns this connector
 * @property {string} mode                 - ConnectorMode value
 * @property {string} [topic]              - Kafka topic, MQTT topic, webhook path
 * @property {string} [eventType]          - e.g. 'row.inserted', 'payment.captured'
 * @property {Date}   producedAt           - when the connector produced it
 * @property {Date}   [originatedAt]       - source timestamp (sensor time, DB commit)
 * @property {*}      payload              - normalized output data
 * @property {string} [payloadSchemaId]    - reference to Schema Registry
 * @property {bigint} [sequenceNumber]     - for ordered streams
 * @property {string} [partitionKey]       - for sharded consumers
 * @property {string} [correlationId]      - trace across workflow steps
 * @property {Object.<string, string>} headers - metadata headers
 * @property {boolean} [isPartial]         - true for streaming batch chunks
 * @property {Object} [error]              - non-fatal error with partial payload
 */

/**
 * Factory function to create a ConnectorEvent with sensible defaults.
 *
 * @param {Object} fields
 * @param {string} fields.connectorType
 * @param {string} fields.connectorInstanceId
 * @param {string} fields.tenantId
 * @param {string} fields.mode - ConnectorMode value
 * @param {*} fields.payload
 * @param {string} [fields.topic]
 * @param {string} [fields.eventType]
 * @param {Date} [fields.originatedAt]
 * @param {string} [fields.correlationId]
 * @param {Object.<string, string>} [fields.headers]
 * @returns {ConnectorEvent}
 */
export function createConnectorEvent(fields) {
  return {
    eventId: randomUUID(),
    connectorType: fields.connectorType,
    connectorInstanceId: fields.connectorInstanceId,
    tenantId: fields.tenantId,
    mode: fields.mode,
    topic: fields.topic ?? null,
    eventType: fields.eventType ?? null,
    producedAt: new Date(),
    originatedAt: fields.originatedAt ?? null,
    payload: fields.payload,
    payloadSchemaId: fields.payloadSchemaId ?? null,
    sequenceNumber: fields.sequenceNumber ?? null,
    partitionKey: fields.partitionKey ?? null,
    correlationId: fields.correlationId ?? null,
    headers: fields.headers ?? {},
    isPartial: fields.isPartial ?? false,
    error: fields.error ?? null,
  };
}

// ─── ConnectorHandle ────────────────────────────────────────────────────────

/**
 * Stateful object returned after connect(). Encapsulates the live connection
 * (DB pool, WebSocket, MQTT client, etc.) and is stored in the ConnectorInstancePool
 * per tenant.
 *
 * @typedef {Object} ConnectorHandle
 * @property {string} handleId          - usually the datasourceID / instanceId
 * @property {string} connectorType     - e.g. 'postgresql', 'mqtt'
 * @property {string} tenantId          - owning tenant
 * @property {'connecting'|'connected'|'degraded'|'disconnected'} status
 * @property {Date}   connectedAt       - when connection was established
 * @property {Date}   [lastHealthCheck] - last successful health check
 * @property {Object} metadata          - connector-specific state (pool, client, etc.)
 * @property {Object} [config]          - the config used to create this handle
 */

/**
 * Factory function to create a ConnectorHandle.
 *
 * @param {Object} fields
 * @param {string} fields.handleId
 * @param {string} fields.connectorType
 * @param {string} fields.tenantId
 * @param {Object} [fields.metadata]
 * @param {Object} [fields.config]
 * @returns {ConnectorHandle}
 */
export function createConnectorHandle(fields) {
  return {
    handleId: fields.handleId,
    connectorType: fields.connectorType,
    tenantId: fields.tenantId,
    status: "connected",
    connectedAt: new Date(),
    lastHealthCheck: null,
    metadata: fields.metadata ?? {},
    config: fields.config ?? null,
  };
}

// ─── ConnectorManifest ──────────────────────────────────────────────────────

/**
 * Declares a connector's capabilities. Used by the registry for capability
 * queries, by the API layer for request validation, and by the frontend for
 * the connector picker UI.
 *
 * @typedef {Object} ConnectorManifest
 * @property {string}   name                - Human-readable name
 * @property {string}   version             - semver — enables runtime compat checks
 * @property {string[]} modes               - ConnectorMode values this connector supports
 * @property {Object}   [configSchema]      - JSON Schema for datasourceOptions
 * @property {Object.<string, Object>} [inputSchemas] - per-mode input schemas
 * @property {Object.<string, Object>} [outputSchemas] - per-mode output schemas
 * @property {string[]} [semanticTags]      - 'database', 'iot', 'finance', 'messaging'
 * @property {string[]} [authSchemes]       - 'oauth2', 'apiKey', 'basic', 'mtls', 'none'
 * @property {Object}   [rateLimits]        - rate limit policy
 * @property {Object}   [retryPolicy]       - retry configuration
 */

// ─── ConnectionTestResult ───────────────────────────────────────────────────

/**
 * @typedef {Object} ConnectionTestResult
 * @property {boolean} ok         - whether the connection succeeded
 * @property {number}  [status]   - HTTP-style status code
 * @property {string}  [statusText] - human-readable status
 * @property {string}  [error]    - error message if !ok
 */

// ─── HealthStatus ───────────────────────────────────────────────────────────

/**
 * @typedef {Object} HealthStatus
 * @property {'healthy'|'unhealthy'|'degraded'} status
 * @property {boolean} [shouldReconnect] - hint to lifecycle manager
 * @property {string}  [message]
 */

// ─── Connector Base Class ───────────────────────────────────────────────────

/**
 * Base class for all connectors. Connectors extend this and implement
 * the lifecycle methods + mode handlers they support.
 *
 * This replaces the flat `{ testConnection, getDatasourceInfo }` shape
 * in DATASOURCE_LOGIC_COMPONENTS with a structured, capability-aware contract.
 *
 * The existing DataSource.execute() pattern is preserved — Connector.pull()
 * wraps it internally for backward compat.
 */
export class Connector {
  /**
   * @param {ConnectorManifest} manifest
   */
  constructor(manifest) {
    if (!manifest || !manifest.name || !manifest.modes) {
      throw new Error("Connector requires a manifest with name and modes");
    }
    /** @type {ConnectorManifest} */
    this._manifest = Object.freeze({ ...manifest });
  }

  /** @returns {ConnectorManifest} */
  get manifest() {
    return this._manifest;
  }

  /**
   * Check if this connector supports a given mode.
   * @param {string} mode - ConnectorMode value
   * @returns {boolean}
   */
  supportsMode(mode) {
    return this._manifest.modes.includes(mode);
  }

  // ── Lifecycle Methods (must be implemented by subclasses) ────────────────

  /**
   * Called when tenant activates this connector instance.
   * Validate config, open persistent connections.
   *
   * @param {Object} config - { datasourceOptions, ... }
   * @param {Object} ctx    - { tenantId, instanceId, eventBus }
   * @returns {Promise<ConnectorHandle>}
   */
  async connect(_config, _ctx) {
    throw new Error(`${this._manifest.name}: connect() not implemented`);
  }

  /**
   * Verify credentials / connectivity without persisting state.
   *
   * @param {Object} config - { datasourceOptions, ... }
   * @returns {Promise<ConnectionTestResult>}
   */
  async testConnection(_config) {
    throw new Error(`${this._manifest.name}: testConnection() not implemented`);
  }

  /**
   * Called on graceful shutdown or config change.
   *
   * @param {ConnectorHandle} handle
   * @returns {Promise<void>}
   */
  async disconnect(_handle) {
    throw new Error(`${this._manifest.name}: disconnect() not implemented`);
  }

  /**
   * Called when config changes while connector is live.
   * Default: disconnect + reconnect.
   *
   * @param {ConnectorHandle} handle
   * @param {Object} newConfig
   * @returns {Promise<void>}
   */
  async reconfigure(_handle, _newConfig) {
    // Default: subclass can override for hot reconfiguration
    return null;
  }

  /**
   * Health probe. Fabric calls this on schedule.
   *
   * @param {ConnectorHandle} handle
   * @returns {Promise<HealthStatus>}
   */
  async healthCheck(_handle) {
    return { status: "healthy" };
  }

  // ── Mode Handlers (implement only what manifest.modes declares) ─────────

  /**
   * PULL: synchronous fetch — replaces DataSource.execute()
   *
   * @param {ConnectorHandle} handle
   * @param {Object} input  - mode-specific input (query, params, etc.)
   * @param {Object} [ctx]  - execution context
   * @returns {Promise<ConnectorEvent[]>}
   */
  async pull(_handle, _input, _ctx) {
    throw new Error(`${this._manifest.name}: pull() not implemented`);
  }

  /**
   * PUSH: write / trigger action
   *
   * @param {ConnectorHandle} handle
   * @param {Object} input  - { payload, topic, ... }
   * @param {Object} [ctx]
   * @returns {Promise<Object>} push result
   */
  async push(_handle, _input, _ctx) {
    throw new Error(`${this._manifest.name}: push() not implemented`);
  }

  /**
   * STREAM: open a long-lived async iterator
   *
   * @param {ConnectorHandle} handle
   * @param {Object} input  - { topics, qos, ... }
   * @param {Object} [ctx]
   * @returns {AsyncIterable<ConnectorEvent>}
   */
  async *stream(_handle, _input, _ctx) {
    throw new Error(`${this._manifest.name}: stream() not implemented`);
  }

  /**
   * SUBSCRIBE: register a durable subscription.
   * Fabric calls onEvent when messages arrive.
   *
   * @param {ConnectorHandle} handle
   * @param {Object} input   - subscription parameters
   * @param {Function} onEvent - callback(ConnectorEvent)
   * @param {Object} [ctx]
   * @returns {Promise<Object>} subscription handle
   */
  async subscribe(_handle, _input, _onEvent, _ctx) {
    throw new Error(`${this._manifest.name}: subscribe() not implemented`);
  }

  /**
   * BATCH: process a large dataset in chunks.
   * Returns an async iterator of { events: ConnectorEvent[], checkpointToken }
   *
   * @param {ConnectorHandle} handle
   * @param {Object} input  - batch parameters
   * @param {Object} [ctx]
   * @returns {AsyncIterable<Object>}
   */
  async *batch(_handle, _input, _ctx) {
    throw new Error(`${this._manifest.name}: batch() not implemented`);
  }

  /**
   * WEBHOOK: process an inbound webhook payload.
   * Called by the WebhookReceiver for each inbound POST.
   *
   * @param {Buffer} rawPayload   - raw request body
   * @param {Object.<string, string>} headers - request headers
   * @param {string} secret       - HMAC secret for verification
   * @returns {Promise<ConnectorEvent[]>}
   */
  async processWebhookPayload(_rawPayload, _headers, _secret) {
    throw new Error(
      `${this._manifest.name}: processWebhookPayload() not implemented`
    );
  }
}
