/**
 * Connector Bootstrap
 *
 * Auto-registers all 28 existing datasources as Connectors in the
 * ConnectorRegistry. Called once at application startup.
 *
 * This bridges the old world (DATASOURCE_LOGIC_COMPONENTS + dataSourceRegistry)
 * and the new world (ConnectorRegistry) without any manual per-datasource work.
 *
 * @module connectors/bootstrap
 */
import { connectorRegistry } from "./registry.js";
import { createConnectorFromDataSource } from "./wrapper-factory.js";
import { CONNECTOR_MANIFESTS } from "./connector-manifests.js";
import { Logger } from "../utils/logger.js";

// ── Import all DataSource classes (same as data-sources/index.js) ───────────
import PostgreSQLDataSource from "../data-sources/postgresql/datasource";
import RestAPIDataSource from "../data-sources/restapi/datasource";
import WebURLDataSource from "../data-sources/weburl/datasource";
import FirestoreDataSource from "../data-sources/firestore/datasource";
import MySQLDataSource from "../data-sources/mysql/datasource";
import MongoDBDataSource from "../data-sources/mongodb/datasource";
import GoogleSheetsDataSource from "../data-sources/googlesheets/datasource";
import GraphQLDataSource from "../data-sources/graphql/datasource";
import RabbitMQDataSource from "../data-sources/rabbitmq/datasource";
import KafkaDataSource from "../data-sources/kafka/datasource";
import RedisDataSource from "../data-sources/redis/datasource";
import MSSQLDataSource from "../data-sources/mssql/datasource";
import SupabaseDataSource from "../data-sources/supabase/datasource";
import BigQueryDataSource from "../data-sources/bigquery/datasource";
import AirtableDataSource from "../data-sources/airtable/datasource";
import S3DataSource from "../data-sources/s3/datasource";
import ElasticsearchDataSource from "../data-sources/elasticsearch/datasource";
import StripeDataSource from "../data-sources/stripe/datasource";
import OracleDataSource from "../data-sources/oracle/datasource";
import SQLiteDataSource from "../data-sources/sqlite/datasource";
import CockroachDBDataSource from "../data-sources/cockroachdb/datasource";
import Neo4jDataSource from "../data-sources/neo4j/datasource";
import TwilioDataSource from "../data-sources/twilio/datasource";
import SendGridDataSource from "../data-sources/sendgrid/datasource";
import SlackDataSource from "../data-sources/slack/datasource";
import NotionDataSource from "../data-sources/notion/datasource";
import JiraDataSource from "../data-sources/jira/datasource";
import GoogleAnalyticsDataSource from "../data-sources/googleanalytics/datasource";

// ── Import all testConnection functions ─────────────────────────────────────
import { postgresqlTestConnection } from "../data-sources/postgresql/connection";
import { restAPITestConnection } from "../data-sources/restapi/connection";
import { webURLTestConnection } from "../data-sources/weburl/connection";
import { firestoreTestConnection } from "../data-sources/firestore/connection";
import { mysqlTestConnection } from "../data-sources/mysql/connection";
import { mongodbTestConnection } from "../data-sources/mongodb/connection";
import { googlesheetsTestConnection } from "../data-sources/googlesheets/connection";
import { graphqlTestConnection } from "../data-sources/graphql/connection";
import { rabbitmqTestConnection } from "../data-sources/rabbitmq/connection";
import { kafkaTestConnection } from "../data-sources/kafka/connection";
import { redisTestConnection } from "../data-sources/redis/connection";
import { mssqlTestConnection } from "../data-sources/mssql/connection";
import { supabaseTestConnection } from "../data-sources/supabase/connection";
import { bigqueryTestConnection } from "../data-sources/bigquery/connection";
import { airtableTestConnection } from "../data-sources/airtable/connection";
import { s3TestConnection } from "../data-sources/s3/connection";
import { elasticsearchTestConnection } from "../data-sources/elasticsearch/connection";
import { stripeTestConnection } from "../data-sources/stripe/connection";
import { oracleTestConnection } from "../data-sources/oracle/connection";
import { sqliteTestConnection } from "../data-sources/sqlite/connection";
import { cockroachdbTestConnection } from "../data-sources/cockroachdb/connection";
import { neo4jTestConnection } from "../data-sources/neo4j/connection";
import { twilioTestConnection } from "../data-sources/twilio/connection";
import { sendgridTestConnection } from "../data-sources/sendgrid/connection";
import { slackTestConnection } from "../data-sources/slack/connection";
import { notionTestConnection } from "../data-sources/notion/connection";
import { jiraTestConnection } from "../data-sources/jira/connection";
import { googleanalyticsTestConnection } from "../data-sources/googleanalytics/connection";

/**
 * Map of type → { DataSourceClass, testConnectionFn }
 * This is the single place that ties types to their implementations.
 */
const DATASOURCE_MAP = {
  postgresql:      { DataSourceClass: PostgreSQLDataSource,      testConnectionFn: postgresqlTestConnection },
  mysql:           { DataSourceClass: MySQLDataSource,           testConnectionFn: mysqlTestConnection },
  mssql:           { DataSourceClass: MSSQLDataSource,           testConnectionFn: mssqlTestConnection },
  oracle:          { DataSourceClass: OracleDataSource,          testConnectionFn: oracleTestConnection },
  sqlite:          { DataSourceClass: SQLiteDataSource,          testConnectionFn: sqliteTestConnection },
  cockroachdb:     { DataSourceClass: CockroachDBDataSource,     testConnectionFn: cockroachdbTestConnection },
  supabase:        { DataSourceClass: SupabaseDataSource,        testConnectionFn: supabaseTestConnection },
  bigquery:        { DataSourceClass: BigQueryDataSource,        testConnectionFn: bigqueryTestConnection },
  mongodb:         { DataSourceClass: MongoDBDataSource,         testConnectionFn: mongodbTestConnection },
  firestore:       { DataSourceClass: FirestoreDataSource,       testConnectionFn: firestoreTestConnection },
  neo4j:           { DataSourceClass: Neo4jDataSource,           testConnectionFn: neo4jTestConnection },
  elasticsearch:   { DataSourceClass: ElasticsearchDataSource,   testConnectionFn: elasticsearchTestConnection },
  airtable:        { DataSourceClass: AirtableDataSource,        testConnectionFn: airtableTestConnection },
  googlesheets:    { DataSourceClass: GoogleSheetsDataSource,    testConnectionFn: googlesheetsTestConnection },
  restapi:         { DataSourceClass: RestAPIDataSource,         testConnectionFn: restAPITestConnection },
  graphql:         { DataSourceClass: GraphQLDataSource,         testConnectionFn: graphqlTestConnection },
  weburl:          { DataSourceClass: WebURLDataSource,          testConnectionFn: webURLTestConnection },
  stripe:          { DataSourceClass: StripeDataSource,          testConnectionFn: stripeTestConnection },
  twilio:          { DataSourceClass: TwilioDataSource,          testConnectionFn: twilioTestConnection },
  sendgrid:        { DataSourceClass: SendGridDataSource,        testConnectionFn: sendgridTestConnection },
  slack:           { DataSourceClass: SlackDataSource,           testConnectionFn: slackTestConnection },
  notion:          { DataSourceClass: NotionDataSource,          testConnectionFn: notionTestConnection },
  jira:            { DataSourceClass: JiraDataSource,            testConnectionFn: jiraTestConnection },
  googleanalytics: { DataSourceClass: GoogleAnalyticsDataSource, testConnectionFn: googleanalyticsTestConnection },
  kafka:           { DataSourceClass: KafkaDataSource,           testConnectionFn: kafkaTestConnection },
  rabbitmq:        { DataSourceClass: RabbitMQDataSource,        testConnectionFn: rabbitmqTestConnection },
  redis:           { DataSourceClass: RedisDataSource,           testConnectionFn: redisTestConnection },
  s3:              { DataSourceClass: S3DataSource,              testConnectionFn: s3TestConnection },
};

let _bootstrapped = false;

/**
 * Bootstrap the ConnectorRegistry with all 28 existing datasources.
 * Safe to call multiple times — only runs once.
 *
 * @returns {{ registered: number, types: string[] }}
 */
export function bootstrapConnectorRegistry() {
  if (_bootstrapped) {
    Logger.log("info", {
      message: "bootstrapConnectorRegistry:alreadyBootstrapped",
      params: { registrySize: connectorRegistry.size },
    });
    return {
      registered: connectorRegistry.size,
      types: connectorRegistry.listTypes(),
    };
  }

  Logger.log("info", {
    message: "bootstrapConnectorRegistry:start",
    params: { datasourceCount: Object.keys(DATASOURCE_MAP).length },
  });

  const registered = [];

  for (const [type, { DataSourceClass, testConnectionFn }] of Object.entries(DATASOURCE_MAP)) {
    const manifest = CONNECTOR_MANIFESTS[type];

    if (!manifest) {
      Logger.log("warning", {
        message: "bootstrapConnectorRegistry:noManifest",
        params: { type },
      });
      continue;
    }

    // Create Connector class via factory
    const ConnectorClass = createConnectorFromDataSource({
      type,
      DataSourceClass,
      testConnectionFn,
      manifest,
    });

    // Register in the ConnectorRegistry
    connectorRegistry.register(type, {
      connectorClass: ConnectorClass,
      manifest,
      // Keep legacy functions for backward compat
      testConnection: testConnectionFn,
    });

    registered.push(type);
  }

  _bootstrapped = true;

  Logger.log("success", {
    message: "bootstrapConnectorRegistry:complete",
    params: {
      registered: registered.length,
      types: registered,
    },
  });

  return {
    registered: registered.length,
    types: registered,
  };
}

/**
 * Check if bootstrap has been called.
 * @returns {boolean}
 */
export function isBootstrapped() {
  return _bootstrapped;
}
