/**
 * Connector Wrapper Factory
 *
 * Creates Connector subclasses from existing DataSource classes and legacy
 * testConnection functions — zero manual work per datasource. This is how
 * all 28 existing datasources become Connectors implementing PULL mode.
 *
 * Usage:
 *   const PostgreSQLConnector = createConnectorFromDataSource({
 *     type: 'postgresql',
 *     DataSourceClass: PostgreSQLDataSource,
 *     testConnectionFn: postgresqlTestConnection,
 *     manifest: { name: 'PostgreSQL', modes: ['PULL'], ... },
 *   });
 *
 * @module connectors/wrapper-factory
 */
import { Connector, createConnectorEvent, createConnectorHandle } from "./contracts.js";
import { Logger } from "../utils/logger.js";

/**
 * @typedef {Object} WrapperFactoryInput
 * @property {string} type                    - connector type key (e.g. 'postgresql')
 * @property {Function} DataSourceClass       - existing DataSource subclass constructor
 * @property {Function} [testConnectionFn]    - legacy testConnection(config) function
 * @property {import('./contracts').ConnectorManifest} manifest - connector manifest
 */

/**
 * Creates a Connector class that wraps an existing DataSource class.
 * The wrapper:
 *   1. Delegates connect()   → creates DataSource instance + stores in handle
 *   2. Delegates testConnection() → calls legacy testConnectionFn
 *   3. Delegates pull()      → calls DataSource.execute()
 *   4. Wraps execute() output in ConnectorEvent for EventBus compatibility
 *
 * @param {WrapperFactoryInput} input
 * @returns {typeof Connector} - a Connector subclass (class, not instance)
 */
export function createConnectorFromDataSource({
  type,
  DataSourceClass,
  testConnectionFn,
  manifest,
}) {
  // Default manifest if not provided
  const resolvedManifest = {
    name: type,
    version: "1.0.0",
    modes: ["PULL"],
    semanticTags: [],
    authSchemes: [],
    ...manifest,
  };

  /**
   * Auto-generated connector wrapping an existing DataSource class.
   */
  class WrappedConnector extends Connector {
    constructor() {
      super(resolvedManifest);
      /** @type {string} */
      this._type = type;
    }

    /**
     * Create a "connection" — for PULL-only connectors, this simply
     * stores the config. The actual DB/API connection happens per-query
     * in execute(), which is the existing DataSource behavior.
     *
     * For stateful connectors (Kafka, Redis, MQTT), this will be
     * overridden in Phase 3 to open persistent connections.
     */
    async connect(config, ctx) {
      Logger.log("info", {
        message: `WrappedConnector:${type}:connect`,
        params: { tenantId: ctx?.tenantId, instanceId: ctx?.instanceId },
      });

      // Create a DataSource instance with the config
      const dsInstance = new DataSourceClass(config);

      return createConnectorHandle({
        handleId: ctx?.instanceId || config?.datasourceID,
        connectorType: type,
        tenantId: ctx?.tenantId,
        metadata: {
          _dsInstance: dsInstance,
          _config: config,
        },
        config,
      });
    }

    /**
     * Test connection — delegates to legacy testConnectionFn.
     */
    async testConnection(config) {
      if (!testConnectionFn) {
        // If no testConnectionFn, try to connect and disconnect
        try {
          const dsInstance = new DataSourceClass(config);
          // No explicit connect for most pull-only datasources
          return { ok: true, status: 200, statusText: "No test available" };
        } catch (error) {
          return { ok: false, error: error.message };
        }
      }

      return testConnectionFn(config.datasourceOptions || config);
    }

    /**
     * Disconnect — no-op for PULL-only connectors.
     * Overridden for stateful connectors (Kafka, Redis) in later phases.
     */
    async disconnect(handle) {
      Logger.log("info", {
        message: `WrappedConnector:${type}:disconnect`,
        params: { handleId: handle?.handleId },
      });
      // No-op for pull-only — connections are per-request
    }

    /**
     * PULL mode — wraps DataSource.execute() and returns ConnectorEvent[].
     *
     * @param {import('./contracts').ConnectorHandle} handle
     * @param {Object} input - dataQueryOptions (query, method, etc.)
     * @param {Object} [ctx]
     * @returns {Promise<import('./contracts').ConnectorEvent[]>}
     */
    async pull(handle, input, ctx) {
      const dsInstance = handle.metadata?._dsInstance;
      if (!dsInstance) {
        throw new Error(
          `WrappedConnector:${type}: no DataSource instance in handle. Was connect() called?`
        );
      }

      Logger.log("info", {
        message: `WrappedConnector:${type}:pull`,
        params: {
          handleId: handle.handleId,
          inputKeys: Object.keys(input || {}),
        },
      });

      // Delegate to the existing DataSource.execute()
      const rawResult = await dsInstance.execute(input, ctx);

      // Wrap result in a ConnectorEvent
      const event = createConnectorEvent({
        connectorType: type,
        connectorInstanceId: handle.handleId,
        tenantId: handle.tenantId,
        mode: "PULL",
        eventType: "query.result",
        payload: rawResult,
      });

      return [event];
    }

    /**
     * PUSH mode — for write-capable datasources.
     * Delegates to DataSource.execute() with the write operation.
     */
    async push(handle, input, ctx) {
      if (!this.supportsMode("PUSH")) {
        throw new Error(`WrappedConnector:${type}: PUSH mode not supported`);
      }

      const dsInstance = handle.metadata?._dsInstance;
      if (!dsInstance) {
        throw new Error(
          `WrappedConnector:${type}: no DataSource instance in handle`
        );
      }

      const rawResult = await dsInstance.execute(input, ctx);

      return {
        success: true,
        result: rawResult,
      };
    }

    /**
     * Health check — for PULL-only connectors, delegates to testConnection.
     */
    async healthCheck(handle) {
      if (!testConnectionFn) {
        return { status: "healthy" };
      }

      try {
        const config = handle.metadata?._config || handle.config;
        const result = await testConnectionFn(
          config?.datasourceOptions || config
        );
        return {
          status: result.ok ? "healthy" : "unhealthy",
          message: result.statusText || result.error,
        };
      } catch (error) {
        return {
          status: "unhealthy",
          shouldReconnect: true,
          message: error.message,
        };
      }
    }
  }

  // Set a nice display name for debugging
  Object.defineProperty(WrappedConnector, "name", {
    value: `${type.charAt(0).toUpperCase() + type.slice(1)}Connector`,
    configurable: true,
  });

  return WrappedConnector;
}
