/**
 * Dead Letter Queue
 *
 * Stores failed events for retry, inspection, and discard.
 * Phase 0: in-memory implementation. The tblEventDLQ table schema
 * is ready for a Prisma-backed implementation in later phases.
 *
 * @module connectors/dlq
 */
import { randomUUID } from "crypto";
import { Logger } from "../utils/logger.js";

/**
 * @typedef {Object} DLQEntry
 * @property {string}  dlqId
 * @property {string}  [eventId]
 * @property {string}  [tenantId]
 * @property {string}  [datasourceId]
 * @property {*}       [rawPayload]
 * @property {Object}  [headers]
 * @property {string}  errorMessage
 * @property {number}  retryCount
 * @property {number}  maxRetries
 * @property {Date}    [nextRetryAt]
 * @property {Date}    [resolvedAt]
 * @property {Date}    createdAt
 */

export class DeadLetterQueue {
  /**
   * @param {Object} [options]
   * @param {number} [options.maxRetries=3]
   * @param {number} [options.baseRetryDelayMs=5000]
   */
  constructor(options = {}) {
    /** @type {Map<string, DLQEntry>} */
    this._entries = new Map();
    this._maxRetries = options.maxRetries ?? 3;
    this._baseRetryDelayMs = options.baseRetryDelayMs ?? 5000;
  }

  /**
   * Push a failed event/payload to the DLQ.
   *
   * @param {Object} params
   * @param {string} [params.eventId]
   * @param {string} [params.tenantId]
   * @param {string} [params.datasourceId]
   * @param {*}      [params.rawPayload]
   * @param {Object} [params.headers]
   * @param {string} params.errorMessage
   * @returns {DLQEntry}
   */
  push(params) {
    const dlqId = randomUUID();
    const retryCount = 0;
    const nextRetryAt = new Date(
      Date.now() + this._baseRetryDelayMs
    );

    /** @type {DLQEntry} */
    const entry = {
      dlqId,
      eventId: params.eventId ?? null,
      tenantId: params.tenantId ?? null,
      datasourceId: params.datasourceId ?? null,
      rawPayload: params.rawPayload ?? null,
      headers: params.headers ?? null,
      errorMessage: params.errorMessage,
      retryCount,
      maxRetries: this._maxRetries,
      nextRetryAt,
      resolvedAt: null,
      createdAt: new Date(),
    };

    this._entries.set(dlqId, entry);

    Logger.log("warning", {
      message: "DeadLetterQueue:push",
      params: {
        dlqId,
        eventId: entry.eventId,
        tenantId: entry.tenantId,
        error: entry.errorMessage,
      },
    });

    return entry;
  }

  /**
   * Get a DLQ entry by ID.
   *
   * @param {string} dlqId
   * @returns {DLQEntry|null}
   */
  get(dlqId) {
    return this._entries.get(dlqId) ?? null;
  }

  /**
   * Get all unresolved entries for a tenant.
   *
   * @param {string} tenantId
   * @returns {DLQEntry[]}
   */
  getByTenant(tenantId) {
    return [...this._entries.values()].filter(
      (e) => e.tenantId === tenantId && !e.resolvedAt
    );
  }

  /**
   * Get all entries due for retry (nextRetryAt <= now, not resolved, under max retries).
   *
   * @returns {DLQEntry[]}
   */
  getRetryable() {
    const now = new Date();
    return [...this._entries.values()].filter(
      (e) =>
        !e.resolvedAt &&
        e.retryCount < e.maxRetries &&
        e.nextRetryAt &&
        e.nextRetryAt <= now
    );
  }

  /**
   * Mark an entry as being retried. Increments retryCount, calculates next retry.
   *
   * @param {string} dlqId
   * @returns {DLQEntry|null}
   */
  markRetried(dlqId) {
    const entry = this._entries.get(dlqId);
    if (!entry) return null;

    entry.retryCount++;
    // Exponential backoff
    const delay =
      this._baseRetryDelayMs * Math.pow(2, entry.retryCount);
    entry.nextRetryAt = new Date(Date.now() + delay);

    Logger.log("info", {
      message: "DeadLetterQueue:markRetried",
      params: {
        dlqId,
        retryCount: entry.retryCount,
        nextRetryAt: entry.nextRetryAt,
      },
    });

    return entry;
  }

  /**
   * Resolve an entry (successfully retried or manually discarded).
   *
   * @param {string} dlqId
   * @returns {boolean}
   */
  resolve(dlqId) {
    const entry = this._entries.get(dlqId);
    if (!entry) return false;

    entry.resolvedAt = new Date();

    Logger.log("info", {
      message: "DeadLetterQueue:resolve",
      params: { dlqId },
    });

    return true;
  }

  /**
   * Discard an entry (remove from DLQ entirely).
   *
   * @param {string} dlqId
   * @returns {boolean}
   */
  discard(dlqId) {
    return this._entries.delete(dlqId);
  }

  /**
   * Get DLQ statistics.
   *
   * @returns {{ total: number, unresolved: number, retryable: number, exhausted: number }}
   */
  getStats() {
    let unresolved = 0;
    let retryable = 0;
    let exhausted = 0;
    const now = new Date();

    for (const entry of this._entries.values()) {
      if (!entry.resolvedAt) {
        unresolved++;
        if (entry.retryCount >= entry.maxRetries) {
          exhausted++;
        } else if (entry.nextRetryAt && entry.nextRetryAt <= now) {
          retryable++;
        }
      }
    }

    return {
      total: this._entries.size,
      unresolved,
      retryable,
      exhausted,
    };
  }

  /**
   * Clear all entries. Used during testing/shutdown.
   */
  clear() {
    this._entries.clear();
  }

  /**
   * Total entries in the DLQ.
   * @returns {number}
   */
  get size() {
    return this._entries.size;
  }
}

/**
 * Singleton DLQ instance.
 */
export const deadLetterQueue = new DeadLetterQueue();
